import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isWarping, setIsWarping] = useState(false);
  const [isPartyTime, setIsPartyTime] = useState(false);

  useEffect(() => {
    // Start the party 1 second in
    const partyTimer = setTimeout(() => setIsPartyTime(true), 1000);
    const warpTimer = setTimeout(() => setIsWarping(true), 3800);
    const finish = setTimeout(onComplete, 4800);

    return () => { 
      clearTimeout(partyTimer);
      clearTimeout(warpTimer); 
      clearTimeout(finish); 
    };
  }, [onComplete]);

  // Our 8-color party palette
  const partyColors = ["#AB1717", "#003366", "#47510B", "#FF5B03", "#FFF24D"];

  return (
    <div className={`h-screen w-full flex items-center justify-center relative overflow-hidden transition-colors duration-100 ${isPartyTime ? 'bg-[#FFF24D]' : 'bg-black'}`}>

      {/* 1. CONFETTI CANNON (The "Magic" Bomb) */}
      {isPartyTime && !isWarping && [...Array(30)].map((_, i) => (
        <motion.div
          key={i}
          initial={{ y: "110vh", x: "50vw", rotate: 0 }}
          animate={{ 
            y: "-10vh", 
            x: `${Math.random() * 100}vw`, 
            rotate: 360,
            scale: [1, 1.5, 0] 
          }}
          transition={{ 
            duration: Math.random() * 2 + 1, 
            repeat: Infinity, 
            ease: "easeOut" 
          }}
          className="confetti absolute opacity-70"
          style={{ backgroundColor: partyColors[i % partyColors.length] }}
        />
      ))}

      <div className={isWarping ? "animate-warp" : "animate-reveal"}>
        <div className="flex flex-col items-center">

          {/* THE LOGO: With the "Jive" Bounce */}
          <div className={`relative flex items-center ${isPartyTime ? "animate-jive" : ""}`}>
            <motion.h1 
              className="text-[12rem] md:text-[20rem] font-[1000] text-[#AB1717] italic tracking-tighter leading-none select-none"
              animate={isPartyTime ? { scale: [1, 1.1, 1] } : {}}
              transition={{ repeat: Infinity, duration: 0.2 }}
            >
              T
              <span className="text-[#AB1717] relative inline-block mx-[-10px] drop-shadow-[0_20px_40px_rgba(171,23,23,0.5)]">
                2
              </span>
              T
            </motion.h1>
          </div>

          {/* THE SUBTITLE: Grassy Green pulsing like a neon sign */}
          <motion.div 
            className="flex items-center mt-[-30px]"
          >
            <span className={`text-[#47510B] font-black text-3xl tracking-[1em] uppercase italic ml-[1em] ${isPartyTime ? "animate-pulse" : ""}`}>
              Worker
            </span>
          </motion.div>
        </div>
      </div>

      {/* 3. LENIN BLUE DECOR: Bottom Disco Bar */}
      <div className="absolute bottom-0 w-full h-4 flex">
        {[...Array(20)].map((_, i) => (
          <div 
            key={i} 
            className={`flex-1 h-full ${i % 2 === 0 ? "bg-[#003366]" : "bg-[#CAD23C]"} ${isPartyTime ? "animate-pulse" : ""}`} 
            style={{ animationDelay: `${i * 0.1}s` }}
          />
        ))}
      </div>

      {/* 4. TACTICAL OVERLAY */}
      <div className="absolute bottom-12 w-full px-16 flex justify-between items-end">
        <div className="font-mono text-[10px] text-[#003366] font-black">
          PARTY_STATUS: COMPILING_JOY
        </div>
        <div className="text-[#AB1717] font-black text-3xl animate-bounce">
          ★ ★ ★
        </div>
      </div>
    </div>
  );
};

export default WorkerSplash;
